package com.reg21meme.dross.boss.golem;

import java.util.List;

/**
 * The Cinder Colossus designs (only the user's pick, 3G Saddleback, is built), their animation timings and what the
 * fight needs to line its hits up with the animations, and the two minions it summons.
 * <p>
 * GENERATED by {@code tools/golems/build.py} from the designs in {@code tools/golems/designs/}: don't edit by hand,
 * change the Python design and run the build again. Each design has its own model, animations and five textures:
 * <ul>
 *   <li>{@code geo/entity/cinder_colossus/<id>.geo.json} and {@code animations/entity/cinder_colossus/<id>.animation.json}</li>
 *   <li>{@code textures/entity/cinder_colossus/<id>.png} (the look), {@code <id>_glow.png} (the parts that glow),
 *       {@code <id>_flow.png} (the lava poured over the shell when the volcano erupts; its alpha says how soon each
 *       pixel is reached), {@code <id>_cracks.png} (the fight's Cracking stage: bright cracks across the shell) and
 *       {@code <id>_statue.png} (the golem cooled into obsidian, faded in when it dies)</li>
 * </ul>
 * Bone names: {@code shell_*} the rock shell, {@code molten_*} lava extras of the core form, {@code vent_*} the core
 * form's live eruption, {@code burst_*} the eruption's blast, {@code prop_*} the rock it throws (shown only while
 * it holds it), {@code *_crater} where the craters are (particles). Every other bone is the lava body, always drawn.
 * <p>
 * Times are in ticks (20 a second) from the start of an animation; points are in the model's own units (16 to a
 * block): x towards its left, y up from its feet, z towards its back (its face is at -z).
 */
public final class GolemDesigns
{
    /**
     * One design.
     *
     * @param number       its place in the showcase row (1 to 1)
     * @param label        its number on the showcase sign (the variations of No. 3 are 3E, 3F...)
     * @param id           file name of its model, animations and textures
     * @param name         its name (fits on a sign)
     * @param mood         one word or two for its style (fits on a sign)
     * @param eruptTicks   length of the eruption animation; afterwards it's erupted
     * @param breakTicks   length of the shell-breaking animation; it holds its last frame afterwards
     * @param burstTicks   when, in that animation, the shell bursts off (the molten extras start to grow then)
     * @param deathTicks   length of the death animation; it holds its last frame afterwards
     * @param walkBlocks   how far the walk animation carries the golem in one loop (the mod speeds the walk up to match
     *                     how fast it really moves)
     * @param walkTicks    length of one walk loop
     * @param moves        its fight moves' timings and where their hits land
     * @param loosePlates  the shell plates the Cracking stage knocks loose
     */
    public record Design(int number, String label, String id, String name, String mood, int eruptTicks, int breakTicks,
                         int burstTicks, int deathTicks, float walkBlocks, int walkTicks, Moves moves,
                         List<LoosePlate> loosePlates)
    {
    }

    /** A point on the model in its own units (x its left, y up, z its back). */
    public record Point(float x, float y, float z)
    {
    }

    /**
     * The fight's moves (animation.cinder_colossus.swipe, throw, slam, charge_start, charge, lob, summon).
     *
     * @param swipeTicks       the backhand swipe's length...
     * @param swipeHit         ...and when its fist sweeps past in front of it (the hit)
     * @param swipeAt          where the fist is then
     * @param throwTicks       the throw's length...
     * @param throwGrab        ...when it tears the rock out of the ground (the rock shows in its fist from here)...
     * @param throwRelease     ...and when it lets go (the thrown rock appears here)
     * @param throwAt          where the rock is when it lets go
     * @param slamTicks        the ground slam's length...
     * @param slamRaised       ...when its fists are up (the warning)...
     * @param slamHit          ...and when they hit the ground (the shockwave)
     * @param slamAt           where they hit (between the two fists)
     * @param chargeStartTicks the charge's wind-up (head down, pawing the ground), before it gallops
     * @param gallopTicks      one loop of the gallop...
     * @param gallopBlocks     ...and how far its strides carry it in one loop
     * @param lobTicks         the volcano lob's length...
     * @param lobRelease       ...and when the lava blobs leave the craters
     * @param craters          the craters at that moment (the blobs start there), left first
     * @param summonTicks      the summoning's length...
     * @param summonPounds     ...and the three pounds (left fist, right fist, both): a minion rises at each
     */
    public record Moves(int swipeTicks, int swipeHit, Point swipeAt, int throwTicks, int throwGrab, int throwRelease,
                        Point throwAt, int slamTicks, int slamRaised, int slamHit, Point slamAt, int chargeStartTicks,
                        int gallopTicks, float gallopBlocks, int lobTicks, int lobRelease, List<Point> craters,
                        int summonTicks, List<Integer> summonPounds)
    {
    }

    /**
     * A shell plate the Cracking stage knocks loose (pushed out and tilted, so lava glows in the gap round it).
     *
     * @param bone  the plate's bone
     * @param push  how far it's pushed (units, along its parent bone's axes)
     * @param tilt  how far it's tilted about its centre (degrees, Bedrock axes)
     * @param from  how cracked the shell is (0 to 1) when it comes loose; it pops out over {@link #LOOSE_POP} more
     */
    public record LoosePlate(String bone, Point push, Point tilt, float from)
    {
    }

    /**
     * A minion's animations (animation.golem_minion.idle, walk, attack, spawn).
     *
     * @param id          file name of its model, animations and textures (geo/entity/golem_minion/<id>.geo.json...)
     * @param attackTicks its punch's length...
     * @param attackHit   ...and when it lands
     * @param spawnTicks  how long it takes to climb out of the ground
     * @param walkBlocks  how far one walk loop carries it...
     * @param walkTicks   ...and the loop's length
     */
    public record Minion(String id, int attackTicks, int attackHit, int spawnTicks, float walkBlocks, int walkTicks)
    {
    }

    public static final List<Design> ALL = List.of(
            new Design(1, "3G", "saddleback", "Saddleback", "big twin peaks", 72, 72, 26, 194, 1.875F, 46,
                    new Moves(29, 12, new Point(-10.11F, 22.30F, -45.71F),
                    46, 12, 28, new Point(-16.20F, 44.89F, -71.48F),
                    52, 15, 30, new Point(0.00F, -0.38F, -39.65F),
                    20, 12, 2.500F, 44, 21, List.of(new Point(14.03F, 81.55F, -2.63F), new Point(-13.66F, 81.63F, -2.50F)),
                    58, List.of(19, 29, 41)),
                    List.of(
                    new LoosePlate("shell_back_l", new Point(0.80F, 0.00F, 1.60F), new Point(5.00F, 0.00F, -4.00F), 0.00F),
                    new LoosePlate("shell_flank_r", new Point(-1.40F, 0.00F, 0.00F), new Point(0.00F, -4.00F, -6.00F), 0.05F),
                    new LoosePlate("shell_upperarm_l", new Point(1.20F, 0.00F, 0.00F), new Point(0.00F, 0.00F, 7.00F), 0.15F),
                    new LoosePlate("shell_chest_r", new Point(-0.50F, 0.00F, -1.30F), new Point(-4.00F, 0.00F, -5.00F), 0.25F),
                    new LoosePlate("shell_thigh_r", new Point(-1.20F, 0.00F, 0.00F), new Point(0.00F, 0.00F, -6.00F), 0.30F),
                    new LoosePlate("shell_traps", new Point(0.00F, 1.20F, 0.60F), new Point(5.00F, 0.00F, 0.00F), 0.40F),
                    new LoosePlate("shell_back_r", new Point(-0.80F, 0.00F, 1.40F), new Point(4.00F, 0.00F, 5.00F), 0.45F),
                    new LoosePlate("shell_pauldron_l", new Point(0.80F, 1.00F, 0.00F), new Point(0.00F, 0.00F, 8.00F), 0.50F),
                    new LoosePlate("shell_flank_l", new Point(1.40F, 0.00F, 0.00F), new Point(0.00F, 4.00F, 7.00F), 0.55F),
                    new LoosePlate("shell_thigh_l", new Point(1.20F, 0.00F, 0.00F), new Point(0.00F, 0.00F, 6.00F), 0.60F),
                    new LoosePlate("shell_chest_l", new Point(0.50F, 0.00F, -1.30F), new Point(-5.00F, 0.00F, 4.00F), 0.70F),
                    new LoosePlate("shell_upperarm_r", new Point(-1.20F, 0.00F, 0.00F), new Point(0.00F, 0.00F, -7.00F), 0.75F),
                    new LoosePlate("shell_pauldron_r", new Point(-0.80F, 1.00F, 0.00F), new Point(0.00F, 0.00F, -8.00F), 0.80F),
                    new LoosePlate("shell_hips", new Point(0.00F, 0.40F, 1.00F), new Point(4.00F, 0.00F, 0.00F), 0.85F))));

    /** The Cracking stage's minions: small golems of stone. */
    public static final Minion STONE_GOLEM = new Minion("stone_golem", 10, 4, 20, 0.875F, 11);
    /** The Lava Core stage's minions: small golems of lava that blow up. */
    public static final Minion LAVA_GOLEM = new Minion("lava_golem", 10, 4, 20, 0.812F, 9);

    /** How strongly the lava glows while dormant (it brightens to full as the lava pours over it in the eruption). */
    public static final float DORMANT_GLOW = 0.45F;
    /** Eruption: seconds into it when the volcano blows (the blast's particles)... */
    public static final float ERUPT_BLAST = 1.3F;
    /** ...and when the lava starts pouring over the shell and when it has covered it (the flow texture's reveal). */
    public static final float FLOW_START = 1.4F;
    public static final float FLOW_END = 3.3F;
    /** Death: the lava's glow fades out between these two times (seconds into the death animation)... */
    public static final float GLOW_FADE_START = 4.0F;
    public static final float GLOW_FADE_END = 7.2F;
    /** ...and the obsidian statue texture fades in between these two. */
    public static final float STATUE_FADE_START = 6.0F;
    public static final float STATUE_FADE_END = 9.6F;
    /** A loose plate pops out over this much of the cracking (0 to 1). */
    public static final float LOOSE_POP = 0.12F;

    /** The design with this number, or the first one if there's none. */
    public static Design byNumber(int number)
    {
        for (Design design : ALL)
        {
            if (design.number() == number)
            {
                return design;
            }
        }
        return ALL.get(0);
    }

    private GolemDesigns() {}
}
